using System.Diagnostics;
using System.Net;
using System.Text.Json.Nodes;
namespace MelavoClient;
sealed partial class Client {
 sealed class FakeSmartProbe(int index,Action<int,string> record):ISmartProbe {
  public Task<(double Delay,double Handshake)> Http204(CancellationToken token){record(index,"http");if(index>=14)throw new TimeoutException();return Task.FromResult((50d+index*10,20d));}
  public Task<double> Throughput(CancellationToken token){record(index,"download");return Task.FromResult(index==0?100d:500d);}
  public ValueTask DisposeAsync()=>ValueTask.CompletedTask;
 }
 public static async Task<int> SmartChecks(string coreFolder){
  var report=new List<string>();void Check(bool value,string name){if(!value)throw new Exception(name);report.Add("PASS: "+name);}var folder=Path.Combine(AppContext.BaseDirectory,"smart-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);Process? engine=null;
  try{
   var metrics=new SmartMetric{HandshakeMs=30,ThroughputKbps=200};metrics.Samples.AddRange(new double?[]{100,110,null,130});Check(metrics.Loss==.25&&metrics.P90==130&&metrics.Jitter==10,"p90 nearest-rank, consecutive-success jitter and packet loss");var expected=(130+10*2.5+30*.4)*Math.Pow(1+.25*4,3)+5000d/201+1600;Check(Math.Abs(metrics.RawCost(2)-expected)<.000001,"exact raw-cost equation");
   Check(!SmartSelection.ShouldSwitch(750,1000)&&SmartSelection.ShouldSwitch(749,1000),"25-percent hysteresis is strict");var historyItem=new SmartHistory{FailCount=4,FailureAt=DateTime.UtcNow.AddMinutes(-10)};Check(Math.Abs(historyItem.DecayedFailures(DateTime.UtcNow)-2)<.01,"failure penalty halves in ten minutes");historyItem.Fail(DateTime.UtcNow);Check(historyItem.FailCount>2.99&&historyItem.CooldownUntil>DateTime.UtcNow,"circuit failure increments decayed penalty and starts cooldown");
   var health=new SmartHealth();Check(!health.Check(false)&&!health.Check(true)&&!health.Check(false)&&health.Check(false),"circuit opens only after two consecutive failed health checks");health.Reset();Check(!health.Observe(0,1)&&!health.Observe(0,2)&&health.Observe(0,3)&&!health.Observe(1,4),"RX stall triggers after three TX-active seconds and resets on download");
   var nodes=Enumerable.Range(0,18).Select(i=>new SmartNode(i.ToString(),i.ToString(),new JsonObject{["index"]=i})).ToArray();var history=new Dictionary<string,SmartHistory>{{"0",new(){Ewma=100}}};var calls=new Dictionary<string,int>();int opening=0,maximum=0;var sync=new object();
   async Task<ISmartProbe> Open(SmartNode node,CancellationToken token){int current=Interlocked.Increment(ref opening);lock(sync)maximum=Math.Max(maximum,current);try{await Task.Delay(20,token);return new FakeSmartProbe(int.Parse(node.Id),(i,kind)=>{lock(sync){var key=i+":"+kind;calls[key]=calls.GetValueOrDefault(key)+1;}});}finally{Interlocked.Decrement(ref opening);}}
   var results=await SmartSelection.Run(nodes,history,Open,(_,_)=>Task.FromResult<double?>(10),null,CancellationToken.None);
   Check(maximum==10,"stage-one opens at most ten parallel probes");Check(results.Count(x=>x.State=="FAKE_PING")==4,"low TCP ping never rescues a failed HTTP tunnel");
   Check(Enumerable.Range(0,5).All(i=>calls[i+":http"]==4)&&Enumerable.Range(5,9).All(i=>calls[i+":http"]==1),"only five finalists receive exactly four HTTP samples");Check(calls.Where(x=>x.Key.EndsWith(":download")).Count()==2,"only top two download 100 KB");
   var best=SmartSelection.Ranked(results).ToArray();Check(best[0].Id=="1"&&best[1].Id=="0"&&best[1].State=="THROTTLED","throttled candidate ranks after healthy throughput without altering cost formula");var zero=results.First(x=>x.Id=="0");Check(Math.Abs(zero.Score!.Value-(.35*zero.RawCost(0)+.65*100))<.000001,"EWMA alpha is 0.35");Check(zero.Quality==(int)Math.Clamp(Math.Round(100-zero.Score.Value/15,MidpointRounding.AwayFromZero),0,100),"quality percentage uses the requested mapping");
   var path=Path.Combine(folder,"history.json");SmartSelection.Save(path,history);var loaded=SmartSelection.Load(path);Check(loaded["0"].Ewma==history["0"].Ewma,"history persists without server credentials");
   using(var canceled=new CancellationTokenSource()){canceled.Cancel();bool rejected=false;try{await SmartSelection.Run(nodes,history,Open,(_,_)=>Task.FromResult<double?>(0),null,canceled.Token);}catch(OperationCanceledException){rejected=true;}Check(rejected,"canceled funnel never selects untested servers");}
   int socks=FreePort(),api=FreePort();JsonArray? baseRules=null;JsonArray Rules(string tag){var rules=(JsonArray)baseRules!.DeepClone();rules.Insert(0,new JsonObject{["type"]="field",["inboundTag"]=new JsonArray("smart-socks"),["outboundTag"]=tag});return rules;}
   var config=new JsonObject{["inbounds"]=new JsonArray(new JsonObject{["tag"]="smart-socks",["listen"]="127.0.0.1",["port"]=socks,["protocol"]="socks",["settings"]=new JsonObject{["auth"]="noauth"}}),["outbounds"]=new JsonArray(new JsonObject{["protocol"]="freedom",["tag"]="original"}),["log"]=new JsonObject{["loglevel"]="warning"}};EnableStats(config,api);config["api"]!["services"]=new JsonArray("StatsService","HandlerService","RoutingService");baseRules=(JsonArray)config["routing"]!["rules"]!.DeepClone();config["routing"]!["rules"]=Rules("original");var configPath=Path.Combine(folder,"core.json");File.WriteAllText(configPath,config.ToJsonString());
   var exe=Path.Combine(coreFolder,"xray.exe");engine=CoreSecurity.Start(new ProcessStartInfo(exe){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=coreFolder,RedirectStandardError=true,RedirectStandardOutput=true,ArgumentList={"run","-c",configPath}});using var job=new CoreJob();job.Add(engine);_=engine.StandardOutput.ReadToEndAsync();_=engine.StandardError.ReadToEndAsync();bool ready=false;for(int i=0;i<50;i++){try{await QueryTraffic(api,"smart-socks");ready=true;break;}catch{await Task.Delay(100);}}Check(ready,"live Xray smart API starts");
   // The actual secured API helper resolves Core() under the app folder. Use explicit verified API process for this isolated fixture.
   async Task Api(string command,JsonObject payload){File.WriteAllText(configPath,payload.ToJsonString());using var proc=CoreSecurity.Start(new ProcessStartInfo(exe){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=coreFolder,RedirectStandardOutput=true,RedirectStandardError=true,ArgumentList={"api",command,"--server=127.0.0.1:"+api,configPath}});var stdout=proc.StandardOutput.ReadToEndAsync();var stderr=proc.StandardError.ReadToEndAsync();using var deadline=new CancellationTokenSource(8000);await proc.WaitForExitAsync(deadline.Token);if(proc.ExitCode!=0)throw new IOException(await stderr);await stdout;}
   var listener=new HttpListener();int web=FreePort();listener.Prefixes.Add($"http://127.0.0.1:{web}/");listener.Start();using var serveCancel=new CancellationTokenSource();var serve=Task.Run(async()=>{try{while(!serveCancel.IsCancellationRequested){var context=await listener.GetContextAsync();context.Response.StatusCode=204;context.Response.Close();}}catch{}});
   async Task<bool> Fetch(){try{using var handler=new SocketsHttpHandler{UseProxy=true,Proxy=new WebProxy($"socks5://127.0.0.1:{socks}")};using var http=new HttpClient(handler){Timeout=TimeSpan.FromSeconds(2)};using var response=await http.GetAsync($"http://127.0.0.1:{web}/");return response.StatusCode==HttpStatusCode.NoContent;}catch{return false;}}
   try{Check(await Fetch(),"original live SOCKS route works");int pid=engine.Id;await Api("ado",new JsonObject{["outbounds"]=new JsonArray(new JsonObject{["protocol"]="blackhole",["tag"]="replacement"})});await Api("adrules",new JsonObject{["routing"]=new JsonObject{["rules"]=Rules("replacement")}});Check(!await Fetch()&&!engine.HasExited&&engine.Id==pid,"route hot-swap applies without restarting Xray or SOCKS inbound");await Api("adrules",new JsonObject{["routing"]=new JsonObject{["rules"]=Rules("original")}});Check(await Fetch()&&engine.Id==pid,"failed-route rollback restores original live tunnel");}
   finally{serveCancel.Cancel();listener.Close();await serve;}
   engine.Kill(true);await engine.WaitForExitAsync();engine.Dispose();engine=null;
   File.WriteAllLines(Path.Combine(AppContext.BaseDirectory,"smart-checks.txt"),report);return 0;
  }catch(Exception e){report.Add("FAIL: "+e);File.WriteAllLines(Path.Combine(AppContext.BaseDirectory,"smart-checks.txt"),report);return 1;}
  finally{if(engine!=null){try{if(!engine.HasExited){engine.Kill(true);await engine.WaitForExitAsync();}}catch{}engine.Dispose();}if(Path.GetFullPath(folder).StartsWith(Path.GetFullPath(AppContext.BaseDirectory)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))Directory.Delete(folder,true);}
 }
